import java.io.*;
import java.util.Base64;

public class SecureDeserialization {
    // This method uses a custom ObjectInputStream to filter deserialized classes
    public static Object deserialize(byte[] data) throws IOException, ClassNotFoundException {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(data);
             ObjectInputStream ois = new FilteringObjectInputStream(bais)) {
            return ois.readObject(); // safe: only allows trusted classes
        }
    }

    // Custom ObjectInputStream that filters allowed classes
    private static class FilteringObjectInputStream extends ObjectInputStream {
        public FilteringObjectInputStream(InputStream in) throws IOException {
            super(in);
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
            String className = desc.getName();
            // Only allow deserialization of trusted classes
            if (!className.equals("com.example.TrustedClass")) {
                throw new InvalidClassException("Unauthorized deserialization attempt", className);
            }
            return super.resolveClass(desc);
        }
    }

    public static void main(String[] args) throws Exception {
        // Simulate receiving serialized data from an untrusted source
        byte[] safeData = getSafeSerializedData(); // Assume this is from a trusted source
        Object obj = deserialize(safeData);
        System.out.println("Deserialized object: " + obj);
    }

    // Dummy method to simulate receiving safe data
    private static byte[] getSafeSerializedData() {
        // In a real application, this would be a trusted serialized byte array
        return new byte[0];
    }
